<?php
namespace App\Filament\Resources\Customers;
use App\Filament\Resources\Concerns\AdminResource; use App\Filament\Resources\Customers\Pages\ManageCustomers; use App\Models\User;
use BackedEnum; use Filament\Actions\EditAction; use Filament\Forms\Components\TextInput; use Filament\Forms\Components\Select; use Filament\Schemas\Schema; use Filament\Support\Icons\Heroicon; use Filament\Tables\Columns\TextColumn; use Filament\Tables\Filters\SelectFilter; use Filament\Tables\Table; use Illuminate\Database\Eloquent\Builder;
class CustomerResource extends AdminResource { protected static ?string $model=User::class; protected static string $viewPermission='customers.view'; protected static ?string $managePermission='customers.update'; protected static string|BackedEnum|null $navigationIcon=Heroicon::OutlinedUsers; protected static ?string $navigationLabel='Khách hàng'; protected static string|\UnitEnum|null $navigationGroup='Khách hàng & Hậu mãi'; protected static ?int $navigationSort=10;
 public static function getEloquentQuery():Builder{return parent::getEloquentQuery()->whereDoesntHave('roles',fn($q)=>$q->where('is_staff',true))->withCount('orders');} public static function form(Schema $s):Schema{return $s->components([TextInput::make('name')->label('Họ tên')->required(),TextInput::make('email')->label('Email')->email()->required()->unique(ignoreRecord:true),TextInput::make('phone')->label('Điện thoại'),Select::make('status')->label('Trạng thái')->options(['active'=>'Hoạt động','blocked'=>'Đã khóa'])->required()]);} public static function table(Table $t):Table{return $t->columns([TextColumn::make('name')->label('Khách hàng')->searchable()->weight('bold'),TextColumn::make('email')->label('Email')->searchable()->copyable(),TextColumn::make('phone')->label('Điện thoại')->searchable(),TextColumn::make('orders_count')->label('Đơn hàng'),TextColumn::make('status')->label('Trạng thái')->badge(),TextColumn::make('created_at')->label('Tham gia')->dateTime('d/m/Y')])->filters([SelectFilter::make('status')->options(['active'=>'Hoạt động','blocked'=>'Đã khóa'])])->recordActions([EditAction::make()->label('Sửa')]);} public static function canCreate():bool{return false;} public static function canDelete(\Illuminate\Database\Eloquent\Model $record):bool{return false;} public static function getPages():array{return ['index'=>ManageCustomers::route('/')];} }
